-- GenDB engine variant Q09-from_permutation: template q09.sql, kind from_permutation (generated by generate.py; frozen)
SELECT
  nation,
  o_year,
  SUM(amount) AS sum_profit
FROM (
  SELECT
    n_name AS nation,
    EXTRACT(YEAR FROM o_orderdate) AS o_year,
    l_extendedprice * (
      1 - l_discount
    ) - ps_supplycost * l_quantity AS amount
  FROM nation, orders, partsupp, lineitem, supplier, part
  WHERE
    s_suppkey = l_suppkey
    AND ps_suppkey = l_suppkey
    AND ps_partkey = l_partkey
    AND p_partkey = l_partkey
    AND o_orderkey = l_orderkey
    AND s_nationkey = n_nationkey
    AND p_name LIKE $1
) AS profit
GROUP BY
  nation,
  o_year
ORDER BY
  nation,
  o_year DESC
